-- NEW-MIS-001: immutable longitudinal Post-Mission evidence.
do $migration$ begin if to_regclass('storage.buckets')is not null then execute $storage$insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('mission-outcome-photos','mission-outcome-photos',false,3145728,array['image/jpeg','image/png','image/webp'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types$storage$;end if;end$migration$;
create table public.mission_outcome_observation_types(id uuid primary key default gen_random_uuid(),code text unique not null,display_name text not null,description text not null default'',display_order integer not null,version integer not null default 1,is_active boolean not null default true);
create table public.mission_outcome_methods(id uuid primary key default gen_random_uuid(),code text unique not null,display_name text not null,description text not null default'',display_order integer not null,version integer not null default 1,is_active boolean not null default true);
create table public.mission_outcome_confidence_levels(id uuid primary key default gen_random_uuid(),code text unique not null,display_name text not null,definition text not null,display_order integer not null,version integer not null default 1);
insert into public.mission_outcome_observation_types(code,display_name,display_order)values('INITIAL','Initial',10),('FOLLOW_UP','Follow-up',20),('FINAL','Final',30),('REGROWTH','Regrowth',40),('CUSTOM','Custom',50);
insert into public.mission_outcome_methods(code,display_name,display_order)values('GROUND_INSPECTION','Ground inspection',10),('AERIAL_INSPECTION','Aerial inspection',20),('REMOTE_IMAGERY','Remote imagery',30),('CUSTOMER_REPORT','Customer report',40),('OTHER','Other',50);
insert into public.mission_outcome_confidence_levels(code,display_name,definition,display_order)values
('HIGH','High','direct, clear and sufficient evidence with minimal uncertainty',10),
('MEDIUM','Medium','credible evidence with identifiable uncertainty or limited coverage',20),
('LOW','Low','limited or indirect evidence; findings are tentative',30);

create table public.mission_outcome_observations(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),operating_location_id uuid not null references public.operating_locations(id),mission_id uuid not null references public.missions(id),completion_revision_id uuid not null references public.mission_completion_revisions(id),sequence_number integer not null,observed_at timestamptz not null,observer_personnel_id uuid not null references public.personnel(id),personnel_snapshot jsonb not null,observation_type_id uuid not null references public.mission_outcome_observation_types(id),observation_type_snapshot jsonb not null,method_id uuid references public.mission_outcome_methods(id),method_snapshot jsonb,confidence_level_id uuid not null references public.mission_outcome_confidence_levels(id),confidence_snapshot jsonb not null,days_since_application integer not null,inspection_time time,approximate_area_inspected_ha numeric check(approximate_area_inspected_ha>=0),inspection_weather jsonb,crop_growth_stage text,target_species text[] not null default'{}',control_percentage numeric check(control_percentage between 0 and 100),regrowth text,off_target_effects text,environmental_observations text,customer_comments text,operator_notes text,recommended_follow_up text,supersedes_observation_id uuid references public.mission_outcome_observations(id),operational_knowledge_eligible boolean not null,eligibility_rule_version integer not null default 1,created_by_internal_user_id uuid not null references public.internal_users(id),created_at timestamptz not null default now(),unique(organisation_id,mission_id,sequence_number));
create table public.mission_outcome_pending_files(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),mission_id uuid not null references public.missions(id),uploaded_by_internal_user_id uuid not null references public.internal_users(id),internal_file_id uuid not null,immutable_file_version integer not null default 1,original_filename text not null,content_type text not null,byte_size integer not null check(byte_size>0 and byte_size<=3145728),sha256_checksum text not null,provider_key text not null,caption text,created_at timestamptz not null default now(),expires_at timestamptz not null default(now()+interval'24 hours'),claimed_at timestamptz);
create table public.mission_outcome_observation_files(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),mission_id uuid not null references public.missions(id),observation_id uuid not null references public.mission_outcome_observations(id),internal_file_id uuid not null,immutable_file_version integer not null,original_filename text not null,content_type text not null,byte_size integer not null,sha256_checksum text not null,provider_key text not null,caption text,provenance jsonb not null,created_at timestamptz not null default now());
create table public.mission_outcome_follow_up_actions(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),operating_location_id uuid not null references public.operating_locations(id),mission_id uuid not null references public.missions(id),source_observation_id uuid not null references public.mission_outcome_observations(id),description text not null,owner_personnel_id uuid references public.personnel(id),due_date date,status text not null check(status in('OPEN','IN_PROGRESS','COMPLETED','CANCELLED')),row_version integer not null default 1,created_by_internal_user_id uuid not null references public.internal_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create function public.ftf_claim_mission_outcome_photos()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin insert into public.mission_outcome_observation_files(organisation_id,mission_id,observation_id,internal_file_id,immutable_file_version,original_filename,content_type,byte_size,sha256_checksum,provider_key,caption,provenance)select p.organisation_id,p.mission_id,new.id,p.internal_file_id,p.immutable_file_version,p.original_filename,p.content_type,p.byte_size,p.sha256_checksum,p.provider_key,p.caption,jsonb_build_object('stagedBy',p.uploaded_by_internal_user_id,'stagedAt',p.created_at,'claimedAt',now())from public.mission_outcome_pending_files p where p.organisation_id=new.organisation_id and p.mission_id=new.mission_id and p.uploaded_by_internal_user_id=new.created_by_internal_user_id and p.claimed_at is null and p.expires_at>now()order by p.created_at limit 10;update public.mission_outcome_pending_files set claimed_at=now()where organisation_id=new.organisation_id and mission_id=new.mission_id and uploaded_by_internal_user_id=new.created_by_internal_user_id and claimed_at is null and expires_at>now();return new;end$$;
create trigger claim_mission_outcome_photos after insert on public.mission_outcome_observations for each row execute function public.ftf_claim_mission_outcome_photos();

do $$declare t text;begin foreach t in array array['mission_outcome_observations','mission_outcome_pending_files','mission_outcome_observation_files','mission_outcome_follow_up_actions']loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('create policy %I on public.%I for select to authenticated using(public.current_user_has_organisation_access(organisation_id))',t||'_tenant_read',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant select,insert on table public.%I to service_role',t);end loop;foreach t in array array['mission_outcome_observations','mission_outcome_observation_files']loop execute format('create trigger %I before update or delete on public.%I for each row execute function public.reject_append_only_mutation()',t||'_immutable',t);end loop;end$$;

create function public.ftf_read_mission_outcomes(p_organisation_id uuid,p_mission_id uuid)returns jsonb language sql security definer set search_path=public,pg_temp as $$select jsonb_build_object('observations',coalesce((select jsonb_agg(to_jsonb(o)||jsonb_build_object('photos',coalesce((select jsonb_agg(to_jsonb(f)order by f.created_at)from public.mission_outcome_observation_files f where f.observation_id=o.id),'[]'))order by o.observed_at,o.sequence_number)from public.mission_outcome_observations o where o.organisation_id=p_organisation_id and o.mission_id=p_mission_id),'[]'),'followUps',coalesce((select jsonb_agg(to_jsonb(f)order by f.created_at)from public.mission_outcome_follow_up_actions f where f.organisation_id=p_organisation_id and f.mission_id=p_mission_id),'[]'),'personnel',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'label',p.full_name)order by p.full_name)from public.personnel p join public.missions m on m.organisation_id=p.organisation_id and m.id=p_mission_id join public.personnel_operating_locations l on l.organisation_id=p.organisation_id and l.personnel_id=p.id and l.operating_location_id=m.operating_location_id where p.organisation_id=p_organisation_id and p.archived_at is null),'[]'),'catalogues',jsonb_build_object('types',(select jsonb_agg(to_jsonb(t)order by t.display_order)from public.mission_outcome_observation_types t where t.is_active),'methods',(select jsonb_agg(to_jsonb(x)order by x.display_order)from public.mission_outcome_methods x where x.is_active),'confidence',(select jsonb_agg(to_jsonb(c)order by c.display_order)from public.mission_outcome_confidence_levels c)))$$;
create function public.ftf_stage_mission_outcome_photo(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare r public.mission_outcome_pending_files%rowtype;begin insert into public.mission_outcome_pending_files(organisation_id,mission_id,uploaded_by_internal_user_id,internal_file_id,original_filename,content_type,byte_size,sha256_checksum,provider_key,caption)values(p_organisation_id,p_mission_id,p_actor_internal_user_id,(p_payload->>'internalFileId')::uuid,p_payload->>'originalFilename',p_payload->>'contentType',(p_payload->>'byteSize')::integer,p_payload->>'checksum',p_payload->>'providerKey',p_payload->>'caption')returning*into r;return jsonb_build_object('record',to_jsonb(r));end$$;
create function public.ftf_create_mission_outcome_observation(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare m public.missions%rowtype;c public.mission_completion_revisions%rowtype;p public.personnel%rowtype;t public.mission_outcome_observation_types%rowtype;md public.mission_outcome_methods%rowtype;cf public.mission_outcome_confidence_levels%rowtype;r public.mission_outcome_observations%rowtype;n integer;eligible boolean;begin select*into m from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null;select*into c from public.mission_completion_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id order by version_number desc limit 1;if not found then return jsonb_build_object('completion_required',true);end if;select*into p from public.personnel where organisation_id=p_organisation_id and id=(p_payload->>'observerPersonnelId')::uuid and archived_at is null;select*into t from public.mission_outcome_observation_types where code=p_payload->>'observationTypeCode' and is_active;select*into md from public.mission_outcome_methods where code=p_payload->>'methodCode' and is_active;select*into cf from public.mission_outcome_confidence_levels where code=p_payload->>'confidenceCode';select coalesce(max(sequence_number),0)+1 into n from public.mission_outcome_observations where organisation_id=p_organisation_id and mission_id=p_mission_id;eligible=coalesce(jsonb_array_length(coalesce(p_payload->'targetSpecies','[]')),0)>0 and p_payload?'controlPercentage' and cf.code in('HIGH','MEDIUM')and(length(trim(coalesce(p_payload->>'operatorNotes','')))>0 or jsonb_array_length(coalesce(p_payload->'pendingFileIds','[]'))>0);insert into public.mission_outcome_observations(organisation_id,operating_location_id,mission_id,completion_revision_id,sequence_number,observed_at,observer_personnel_id,personnel_snapshot,observation_type_id,observation_type_snapshot,method_id,method_snapshot,confidence_level_id,confidence_snapshot,days_since_application,inspection_time,approximate_area_inspected_ha,inspection_weather,crop_growth_stage,target_species,control_percentage,regrowth,off_target_effects,environmental_observations,customer_comments,operator_notes,recommended_follow_up,supersedes_observation_id,operational_knowledge_eligible,created_by_internal_user_id)values(p_organisation_id,m.operating_location_id,m.id,c.id,n,(p_payload->>'observedAt')::timestamptz,p.id,jsonb_build_object('id',p.id,'name',p.full_name),t.id,to_jsonb(t),md.id,to_jsonb(md),cf.id,to_jsonb(cf),greatest(0,floor(extract(epoch from((p_payload->>'observedAt')::timestamptz-c.created_at))/86400)::integer),nullif(p_payload->>'inspectionTime','')::time,nullif(p_payload->>'approximateAreaInspectedHa','')::numeric,p_payload->'inspectionWeather',p_payload->>'cropGrowthStage',array(select jsonb_array_elements_text(coalesce(p_payload->'targetSpecies','[]'))),nullif(p_payload->>'controlPercentage','')::numeric,p_payload->>'regrowth',p_payload->>'offTargetEffects',p_payload->>'environmentalObservations',p_payload->>'customerComments',p_payload->>'operatorNotes',p_payload->>'recommendedFollowUp',nullif(p_payload->>'supersedesObservationId','')::uuid,eligible,p_actor_internal_user_id)returning*into r;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.outcome_observed','mission_outcome_observation',r.id,jsonb_build_object('mission_id',m.id,'sequence',n));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'post_mission.mission.outcome_observed','mission',m.id,jsonb_build_object('observation_id',r.id));return jsonb_build_object('record',to_jsonb(r));end$$;
create function public.ftf_write_mission_outcome_follow_up(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_action_id uuid,p_expected_version integer,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare r public.mission_outcome_follow_up_actions%rowtype;begin if p_action_id is null then insert into public.mission_outcome_follow_up_actions(organisation_id,operating_location_id,mission_id,source_observation_id,description,owner_personnel_id,due_date,status,created_by_internal_user_id)select p_organisation_id,m.operating_location_id,m.id,(p_payload->>'sourceObservationId')::uuid,p_payload->>'description',nullif(p_payload->>'ownerPersonnelId','')::uuid,nullif(p_payload->>'dueDate','')::date,coalesce(p_payload->>'status','OPEN'),p_actor_internal_user_id from public.missions m where m.organisation_id=p_organisation_id and m.id=p_mission_id returning*into r;else update public.mission_outcome_follow_up_actions set description=p_payload->>'description',owner_personnel_id=nullif(p_payload->>'ownerPersonnelId','')::uuid,due_date=nullif(p_payload->>'dueDate','')::date,status=p_payload->>'status',row_version=row_version+1,updated_at=now()where organisation_id=p_organisation_id and mission_id=p_mission_id and id=p_action_id and row_version=p_expected_version returning*into r;if not found then return jsonb_build_object('conflict',true);end if;end if;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.outcome_follow_up_changed','mission_outcome_follow_up',r.id,'{}');insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'post_mission.mission.outcome_follow_up_changed','mission',p_mission_id,jsonb_build_object('follow_up_id',r.id));return jsonb_build_object('record',to_jsonb(r));end$$;

create function public.ftf_provision_mission_outcome_permissions()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin insert into public.permissions(organisation_id,code,description)select new.organisation_id,v.code,v.description from(values('mission.outcomes.read','View Mission Outcomes'),('mission.outcomes.create','Record Mission Outcomes'),('mission.outcomes.photo.upload','Upload Mission Outcome photos'),('mission.outcomes.follow_up.manage','Manage Mission Outcome follow-up actions'))v(code,description)on conflict(organisation_id,code)do nothing;if new.code='admin'then insert into public.role_permissions(organisation_id,role_id,permission_id)select new.organisation_id,new.id,p.id from public.permissions p where p.organisation_id=new.organisation_id and p.code like'mission.outcomes.%'on conflict do nothing;end if;return new;end$$;
create trigger provision_mission_outcome_permissions after insert on public.roles for each row execute function public.ftf_provision_mission_outcome_permissions();
insert into public.permissions(organisation_id,code,description)select o.id,v.code,v.description from public.organisations o cross join(values('mission.outcomes.read','View Mission Outcomes'),('mission.outcomes.create','Record Mission Outcomes'),('mission.outcomes.photo.upload','Upload Mission Outcome photos'),('mission.outcomes.follow_up.manage','Manage Mission Outcome follow-up actions'))v(code,description)on conflict(organisation_id,code)do nothing;
insert into public.role_permissions(organisation_id,role_id,permission_id)select r.organisation_id,r.id,p.id from public.roles r join public.permissions p on p.organisation_id=r.organisation_id and p.code like'mission.outcomes.%'where r.code='admin'on conflict do nothing;
revoke all on function public.ftf_read_mission_outcomes(uuid,uuid),public.ftf_stage_mission_outcome_photo(uuid,uuid,uuid,jsonb),public.ftf_create_mission_outcome_observation(uuid,uuid,uuid,jsonb),public.ftf_write_mission_outcome_follow_up(uuid,uuid,uuid,uuid,integer,jsonb)from public,anon,authenticated;
grant execute on function public.ftf_read_mission_outcomes(uuid,uuid),public.ftf_stage_mission_outcome_photo(uuid,uuid,uuid,jsonb),public.ftf_create_mission_outcome_observation(uuid,uuid,uuid,jsonb),public.ftf_write_mission_outcome_follow_up(uuid,uuid,uuid,uuid,integer,jsonb)to service_role;
